<?php get_header(); ?><main class="container section"><header class="archive-head"><span class="eyebrow">SEARCH</span><h1>搜尋結果</h1><p>「<?php echo esc_html(get_search_query()); ?>」的搜尋結果</p></header><?php if(have_posts()): ?><div class="store-grid"><?php while(have_posts()):the_post();get_template_part('template-parts/store-card');endwhile; ?></div><?php the_posts_pagination(array('mid_size'=>1,'prev_text'=>'←','next_text'=>'→'));else: ?><div class="empty-state"><h2>找不到相關店家</h2><p>請嘗試其他店家名稱、城市或類型。</p><form class="hero-search compact" action="<?php echo esc_url(home_url('/')); ?>"><input name="s" type="search" value="<?php echo esc_attr(get_search_query()); ?>" placeholder="重新搜尋"><button type="submit">搜尋</button></form></div><?php endif; ?></main><?php get_footer(); ?>
